// Fixtures calls GET /v2/teams/{id}/fixtures: Team fixtures.
//
// Plans: free, starter, pro, business, enterprise.
//
// Docs: https://datasportsapi.com/docs/teams/fixtures/
func (s *TeamsService) Fixtures(ctx context.Context, id int64, params *TeamsFixturesParams) (*TeamsFixturesResponse, error) {
	out := new(TeamsFixturesResponse)
	if err := s.c.do(ctx, "GET", "/v2/teams/"+strconv.FormatInt(id, 10)+"/fixtures", params.query(), nil, out); err != nil {
		return nil, err
	}
	return out, nil
}

// FixturesPages walks Fixtures page by page and yields each page's envelope. It stops after the last page, on the first error (yielded once), when the loop breaks, or after MaxPages(n) pages.
func (s *TeamsService) FixturesPages(ctx context.Context, id int64, params *TeamsFixturesParams, opts ...PageOption) iter.Seq2[*TeamsFixturesResponse, error] {
	return func(yield func(*TeamsFixturesResponse, error) bool) {
		var p TeamsFixturesParams
		if params != nil {
			p = *params
		}
		limit := pageLimit(opts)
		for n := 0; limit <= 0 || n < limit; n++ {
			res, err := s.Fixtures(ctx, id, &p)
			if err != nil {
				yield(nil, err)
				return
			}
			if !yield(res, nil) {
				return
			}
			var m pageMeta
			if res.Meta != nil {
				m.hasNextPage = res.Meta.HasNextPage
				m.page = res.Meta.Page
			}
			next, ok := m.next(p.Page, false)
			if !ok {
				return
			}
			p.Page = &next.page
		}
	}
}

