type LivescoresWireParams struct {
	// sport slug; only that sport’s moments (all sports when left out). One of: football, tennis, basketball, ice-hockey, esports, volleyball, handball, baseball, american-football, rugby, cricket, mma, table-tennis, darts, snooker, futsal, badminton, waterpolo, cycling, motorsport, minifootball, floorball, bandy, padel, aussie-rules.
	Sport *string
	// ISO 8601 instant; only moments after it, for example the newest at you already hold.
	Since *string
	// ISO 8601 instant; only moments before it, which pages backwards (send the oldest at you received).
	Before *string
	// number of moments, 1–100 (30 when left out). Default: 30.
	Limit *int64
}

func (p *LivescoresWireParams) query() url.Values {
	q := url.Values{}
	if p == nil {
		return q
	}
	if p.Sport != nil {
		q.Set("sport", *p.Sport)
	}
	if p.Since != nil {
		q.Set("since", *p.Since)
	}
	if p.Before != nil {
		q.Set("before", *p.Before)
	}
	if p.Limit != nil {
		q.Set("limit", strconv.FormatInt(*p.Limit, 10))
	}
	return q
}

// FixturesListParams holds the query parameters of List (GET /v2/fixtures). Required fields are values; optional ones are pointers (set them with Ptr) and are left out when nil.
type FixturesListParams struct {
	// UTC date as YYYY-MM-DD (a local day with tz), from 1990-01-01 to one year in the future. A multi-day cricket match appears on each day it is played (since 2026-11-24). Required.
	Date string
	// sport slug; leave sport, league and category all out to get every sport’s day, read by cursor (since 2026-11-24). One of: football, tennis, basketball, ice-hockey, esports, volleyball, handball, baseball, american-football, rugby, cricket, mma, table-tennis, darts, snooker, futsal, badminton, waterpolo, cycling, motorsport, minifootball, floorball, bandy, padel, aussie-rules.
	Sport *string
	// league id — returns only that league’s fixtures for the date, on a single page (page has to be 0).
	League *int64
	// category id, as listed by /v2/categories or /v2/fixtures/counts — all leagues of that country, region or tour for the date, sorted by start time, on a single page (page has to be 0). Available since 2026-11-04.
	Category *int64
	// two-letter Country.code (EN, ES, US …; case-insensitive), used together with sport — returns the date’s fixtures from that country’s categories in the sport, on a single page. Available since 2026-11-04.
	Country *string
	// only when sport is the sole filter: page index 0–99 (defaults to 0), each page covering 10 leagues. A league with no fixture that day can leave a page short or even empty; cursor does not. Default: 0.
	Page *int64
	// the meta.nextCursor of the previous page, used instead of page with sport alone or with no filter at all. A cursor works for one hour and only with the sport and date it came from. Available since 2026-11-23.
	Cursor *string
	// reads date as a day in your own time: give an IANA zone name (Europe/London, America/New_York), which tracks summer time, so the day the clocks change is 23 or 25 hours long, or a plain offset from -12:00 to +14:00 (+03:00, -05:00, +3, +0530; send + encoded as %2B, since a bare + arrives as a space). You get the fixtures that begin inside that local day, with start times kept in UTC, and meta reports tz plus utcFrom and utcTo, where the day begins and ends in UTC. Leave tz out and the day is a UTC one. Available since 2026-11-24.
	Tz *string
}

func (p *FixturesListParams) query() url.Values {
	q := url.Values{}
	if p == nil {
		return q
	}
	q.Set("date", p.Date)
	if p.Sport != nil {
		q.Set("sport", *p.Sport)
	}
	if p.League != nil {
		q.Set("league", strconv.FormatInt(*p.League, 10))
	}
	if p.Category != nil {
		q.Set("category", strconv.FormatInt(*p.Category, 10))
	}
	if p.Country != nil {
		q.Set("country", *p.Country)
	}
	if p.Page != nil {
		q.Set("page", strconv.FormatInt(*p.Page, 10))
	}
	if p.Cursor != nil {
		q.Set("cursor", *p.Cursor)
	}
	if p.Tz != nil {
		q.Set("tz", *p.Tz)
	}
	return q
}

